 "hf-t1-historicidad": {
  "name": "Historicity and universality (HF · T1)",
  "subject": "hf",
  "block": "A",
  "items": [
   {
    "q": "The ‘historicity’ of philosophy means that…",
    "o": [
     "each philosophy is born in a specific historical and cultural context.",
     "philosophy never changes.",
     "only ancient history matters.",
     "philosophy is an exact science."
    ],
    "a": 0,
    "fb": "Historicity: all thought arises situated in its time and its culture."
   },
   {
    "q": "The ‘universality’ of philosophy refers to the fact that…",
    "o": [
     "everyone thinks the same.",
     "certain questions (being, the good, truth) reappear in different eras and cultures.",
     "there is only one true answer.",
     "philosophy is universal in school."
    ],
    "a": 1,
    "fb": "Universality: there are problems that come back again and again, beyond any one era."
   },
   {
    "q": "How are historicity and universality related?",
    "o": [
     "They exclude each other.",
     "They are not opposed: universal questions receive historical, situated answers.",
     "They are the same.",
     "Neither is real."
    ],
    "a": 1,
    "fb": "Questions that repeat, answers that depend on context."
   },
   {
    "q": "That philosophy is transmitted through ‘schools and networks’ means that…",
    "o": [
     "thought circulates among teachers, disciples and institutions, not in isolation.",
     "each philosopher works in isolation.",
     "it is only learned on the internet.",
     "it cannot be taught."
    ],
    "a": 0,
    "fb": "Philosophy is inherited and debated in community."
   },
   {
    "q": "The philosophical ‘canon’ is…",
    "o": [
     "a law.",
     "the set of authors and works that a tradition considers indispensable.",
     "an exam.",
     "a type of argument."
    ],
    "a": 1,
    "fb": "Canon: the list of references that a tradition takes as basic."
   },
   {
    "q": "One criticism of the traditional canon is that…",
    "o": [
     "it was too long.",
     "it left out many voices (for example women or non-European thinkers).",
     "it included everyone.",
     "it was too modern."
    ],
    "a": 1,
    "fb": "The classical canon made important contributions invisible."
   },
   {
    "q": "Studying philosophy ‘historically’ helps to…",
    "o": [
     "memorise dates for their own sake.",
     "understand why each idea arose and not read it out of its time.",
     "avoid thinking.",
     "prove theorems."
    ],
    "a": 1,
    "fb": "Context explains the meaning of each proposal."
   },
   {
    "q": "The fact that the same questions reappear does NOT mean that…",
    "o": [
     "they are important.",
     "the answers are always the same.",
     "they interest many people.",
     "they have to do with reality."
    ],
    "a": 1,
    "fb": "Same question, different answers depending on the era."
   },
   {
    "q": "Western philosophy is usually said to begin in…",
    "o": [
     "Greece in the 6th century BC (the passage from myth to logos).",
     "Imperial Rome.",
     "the Middle Ages.",
     "the Renaissance."
    ],
    "a": 0,
    "fb": "With the Greek pre-Socratics: from myth to logos."
   },
   {
    "q": "Recognising the historicity of one’s own thought invites…",
    "o": [
     "believing oneself to be in possession of absolute truth.",
     "humility and self-criticism: our own ideas are situated too.",
     "giving up studying.",
     "despising the past."
    ],
    "a": 1,
    "fb": "If all thought is historical, ours is too."
   }
  ]
 },
